//! Oracle vectors of the runtime parity fixes of `research/fuzzing.md` (group G2; item history:
//! `git log -- plans/parity-fixes.md`): templates whose results Twig 3.31.1 on PHP 8.5.13 produced
//! (`twig-oracle:3.31.1`), replayed through the twig-fuzz runner and diff like `tests/fuzz_regressions.rs` (output
//! bytes, error class, message, line, previous errors, deprecations and diagnostics; only the deviations of
//! `reference/deviations.md` that twig-fuzz knows are accepted).
//!
//! - `p17-*`: `{% deprecated %}` passes `package` and `version` to `trigger_deprecation(string $package, string
//!   $version, ...)` (coercive `string` parameters, checked after the message conversion).
//! - `p18-*`: `attribute()`'s third argument is `CoreExtension::getAttribute()`'s `array $arguments`.
//! - `p19-*`: `include()`, `include_only()` and `source()` bind their arguments, named spreads included, to the PHP
//!   signatures (`func_num_args()` for the `sandboxed` deprecation).
//! - `p21-*`: a canonical integer class key of a policy makes `instanceof` throw when the loop reaches it.
//! - `p22-*`: a sandbox violation of a name first used at line 0 gets the last line marker of the class.
//!
//! To regenerate, write the `case` of every vector into a batch, then `twig-fuzz oracle batch.json --out o.json` and
//! `twig-fuzz record batch.json --oracle o.json --out v.json` (needs Docker; research/php-oracle).

use std::time::Duration;

#[allow(dead_code)]
#[path = "../crates/twig-fuzz/src/kit/mod.rs"]
mod kit;

use kit::json::Json;
use kit::vectors::{ReplayStatus, VectorFile, replay};

/// Replays the vectors whose id starts with `prefix`; fails with every difference.
fn replay_vectors(prefix: &str) {
    let json = Json::parse(VECTORS).expect("the embedded vectors are JSON");
    let file = VectorFile::from_json(&json).expect("the embedded vectors have the vector format");
    let mut count = 0;
    let mut failures = Vec::new();
    for vector in file.vectors.iter().filter(|v| v.id.starts_with(prefix)) {
        count += 1;
        match replay(vector, Duration::from_secs(60)) {
            ReplayStatus::Pass | ReplayStatus::PassWithDeviation(_) => {}
            other => failures.push(format!("{}: {other:?}", vector.id)),
        }
    }
    assert!(count > 0, "no vector starts with {prefix}");
    assert!(
        failures.is_empty(),
        "{} of {count} vectors differ from the oracle:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn deprecated_tag_types_package_and_version_as_strings() {
    replay_vectors("p17-");
}

#[test]
fn attribute_arguments_must_be_an_array() {
    replay_vectors("p18-");
}

#[test]
fn template_functions_bind_their_arguments_like_php() {
    replay_vectors("p19-");
}

#[test]
fn integer_policy_class_keys_throw_when_reached() {
    replay_vectors("p21-");
}

#[test]
fn violations_of_names_used_at_line_zero_take_the_last_marker() {
    replay_vectors("p22-");
}

